on conflict (slug) do update set
  category_id = excluded.category_id,
  name = excluded.name,
  description = excluded.description,
  price = excluded.price,
  thumbnail_url = excluded.thumbnail_url,
  search_text = excluded.search_text;

-- 3. PRODUCT VARIANTS (Size M, L, XL - SKU duy nhat khong trung lap - Stock thuc te)
insert into product_variants (product_id, size, color, sku, stock)
select
  p.id as product_id,
  s.size,
  c.color,
  'SKU-' || upper(substr(replace(p.slug, '-', ''), 1, 5)) || '-' || substr(p.id::text, 33, 4) || '-' || s.size as sku,
  (30 + (random() * 40)::int) as stock
from products p
cross join (values ('M'), ('L'), ('XL')) as s(size)
cross join (values ('Tiêu chuẩn')) as c(color)
on conflict (product_id, size, color) do update set sku = excluded.sku, stock = excluded.stock;

-- 4. PRODUCT IMAGES (Thu vien anh san pham - chong trung lap)
insert into product_images (product_id, url, sort_order)
select
  p.id,
  p.thumbnail_url,
  1
from products p
where not exists (
  select 1 from product_images pi where pi.product_id = p.id
);

-- 5. DEFAULT ADMIN ACCOUNT (admin@gmail.com / 123456)
do $$
declare
  admin_uid uuid := '00000000-0000-0000-0000-000000000001';
begin
  if not exists (select 1 from auth.users where email = 'admin@gmail.com') then
    insert into auth.users (
      id,
      instance_id,
      email,
      encrypted_password,
      email_confirmed_at,
      raw_app_meta_data,
      raw_user_meta_data,
      created_at,
      updated_at,
      role,
      aud
    ) values (
      admin_uid,
      '00000000-0000-0000-0000-000000000000',
      'admin@gmail.com',
      crypt('123456', gen_salt('bf')),
      now(),
      '{"provider":"email","providers":["email"]}',
      '{"full_name":"Admin MenShop","role":"admin"}',
      now(),
      now(),
      'authenticated',
      'authenticated'
    );
  end if;

  insert into public.profiles (id, email, full_name, role, is_guest, is_active, is_locked)
  values (
    (select id from auth.users where email = 'admin@gmail.com'),
    'admin@gmail.com',
    'Admin MenShop',
    'admin',
    false,
    true,
    false
  )
  on conflict (id) do update set
    email = 'admin@gmail.com',
    role = 'admin',
    is_active = true,
    is_locked = false;
end $$;
